package br.edu.oficinacampus.dominio.catalogo;

import br.edu.oficinacampus.dominio.compartilhado.*;
import org.junit.jupiter.api.*;
import java.util.*;
import java.util.stream.Stream;
import static org.junit.jupiter.api.Assertions.*;

/** Constrói os agregados diretamente: regras não dependem do JSON da interface. */
class InvariantesCatalogoTest {
    @TestFactory Stream<DynamicTest> invariantesDosAgregados() {
        List<DynamicTest> testes = new ArrayList<>();
        testes.add(DynamicTest.dynamicTest("oficinas: exemplo válido", () -> assertDoesNotThrow(() -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 120))));
        testes.add(DynamicTest.dynamicTest("oficinas/titulo: obrigatório", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), null, "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 120))));
        testes.add(DynamicTest.dynamicTest("oficinas/titulo: texto extenso", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 120))));
        testes.add(DynamicTest.dynamicTest("oficinas/apresentacao: obrigatório", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", null, "Presencial", 120))));
        testes.add(DynamicTest.dynamicTest("oficinas/apresentacao: texto extenso", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "", "Presencial", 120))));
        testes.add(DynamicTest.dynamicTest("oficinas/modalidade: obrigatório", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", null, 120))));
        testes.add(DynamicTest.dynamicTest("oficinas/modalidade: opção inválida", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Inexistente", 120))));
        testes.add(DynamicTest.dynamicTest("oficinas/modalidade: texto extenso", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", 120))));
        testes.add(DynamicTest.dynamicTest("oficinas/duracao: obrigatório", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", null))));
        testes.add(DynamicTest.dynamicTest("oficinas/duracao: abaixo do mínimo", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 0))));
        testes.add(DynamicTest.dynamicTest("oficinas/duracao: acima do máximo", () -> assertThrows(ErroDominio.class, () -> new Oficina(Controle.novo(Estado.ATIVO), "Introdução à programação criativa", "Explore lógica e criatividade construindo pequenas experiências interativas.", "Presencial", 481))));
        testes.add(DynamicTest.dynamicTest("interesses: exemplo válido", () -> assertDoesNotThrow(() -> new ManifestacaoInteresse(Controle.novo(Estado.ATIVO), "Ana Lima", "ana@example.com", "Python para iniciantes", "Online"))));
        testes.add(DynamicTest.dynamicTest("interesses/nome: obrigatório", () -> assertThrows(ErroDominio.class, () -> new ManifestacaoInteresse(Controle.novo(Estado.ATIVO), null, "ana@example.com", "Python para iniciantes", "Online"))));
        testes.add(DynamicTest.dynamicTest("interesses/nome: texto extenso", () -> assertThrows(ErroDominio.class, () -> new ManifestacaoInteresse(Controle.novo(Estado.ATIVO), "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "ana@example.com", "Python para iniciantes", "Online"))));
        testes.add(DynamicTest.dynamicTest("interesses/email: obrigatório", () -> assertThrows(ErroDominio.class, () -> new ManifestacaoInteresse(Controle.novo(Estado.ATIVO), "Ana Lima", null, "Python para iniciantes", "Online"))));
        testes.add(DynamicTest.dynamicTest("interesses/email: email inválido", () -> assertThrows(ErroDominio.class, () -> new ManifestacaoInteresse(Controle.novo(Estado.ATIVO), "Ana Lima", "email-invalido", "Python para iniciantes", "Online"))));
        testes.add(DynamicTest.dynamicTest("interesses/email: texto extenso", () -> assertThrows(ErroDominio.class, () -> new ManifestacaoInteresse(Controle.novo(Estado.ATIVO), "Ana Lima", "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "Python para iniciantes", "Online"))));
        testes.add(DynamicTest.dynamicTest("interesses/tema: obrigatório", () -> assertThrows(ErroDominio.class, () -> new ManifestacaoInteresse(Controle.novo(Estado.ATIVO), "Ana Lima", "ana@example.com", null, "Online"))));
        testes.add(DynamicTest.dynamicTest("interesses/tema: texto extenso", () -> assertThrows(ErroDominio.class, () -> new ManifestacaoInteresse(Controle.novo(Estado.ATIVO), "Ana Lima", "ana@example.com", "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "Online"))));
        testes.add(DynamicTest.dynamicTest("interesses/modalidade: obrigatório", () -> assertThrows(ErroDominio.class, () -> new ManifestacaoInteresse(Controle.novo(Estado.ATIVO), "Ana Lima", "ana@example.com", "Python para iniciantes", null))));
        testes.add(DynamicTest.dynamicTest("interesses/modalidade: opção inválida", () -> assertThrows(ErroDominio.class, () -> new ManifestacaoInteresse(Controle.novo(Estado.ATIVO), "Ana Lima", "ana@example.com", "Python para iniciantes", "Inexistente"))));
        testes.add(DynamicTest.dynamicTest("interesses/modalidade: texto extenso", () -> assertThrows(ErroDominio.class, () -> new ManifestacaoInteresse(Controle.novo(Estado.ATIVO), "Ana Lima", "ana@example.com", "Python para iniciantes", "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"))));
        testes.add(DynamicTest.dynamicTest("instrutores: exemplo válido", () -> assertDoesNotThrow(() -> new Instrutor(Controle.novo(Estado.ATIVO), "Marina Alves", "Educadora com experiência em oficinas práticas de tecnologia.", "Programação criativa", "marina@example.com"))));
        testes.add(DynamicTest.dynamicTest("instrutores/nome: obrigatório", () -> assertThrows(ErroDominio.class, () -> new Instrutor(Controle.novo(Estado.ATIVO), null, "Educadora com experiência em oficinas práticas de tecnologia.", "Programação criativa", "marina@example.com"))));
        testes.add(DynamicTest.dynamicTest("instrutores/nome: texto extenso", () -> assertThrows(ErroDominio.class, () -> new Instrutor(Controle.novo(Estado.ATIVO), "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "Educadora com experiência em oficinas práticas de tecnologia.", "Programação criativa", "marina@example.com"))));
        testes.add(DynamicTest.dynamicTest("instrutores/apresentacao: obrigatório", () -> assertThrows(ErroDominio.class, () -> new Instrutor(Controle.novo(Estado.ATIVO), "Marina Alves", null, "Programação criativa", "marina@example.com"))));
        testes.add(DynamicTest.dynamicTest("instrutores/apresentacao: texto extenso", () -> assertThrows(ErroDominio.class, () -> new Instrutor(Controle.novo(Estado.ATIVO), "Marina Alves", "", "Programação criativa", "marina@example.com"))));
        testes.add(DynamicTest.dynamicTest("instrutores/especialidade: obrigatório", () -> assertThrows(ErroDominio.class, () -> new Instrutor(Controle.novo(Estado.ATIVO), "Marina Alves", "Educadora com experiência em oficinas práticas de tecnologia.", null, "marina@example.com"))));
        testes.add(DynamicTest.dynamicTest("instrutores/especialidade: texto extenso", () -> assertThrows(ErroDominio.class, () -> new Instrutor(Controle.novo(Estado.ATIVO), "Marina Alves", "Educadora com experiência em oficinas práticas de tecnologia.", "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "marina@example.com"))));
        testes.add(DynamicTest.dynamicTest("instrutores/contato: texto extenso", () -> assertThrows(ErroDominio.class, () -> new Instrutor(Controle.novo(Estado.ATIVO), "Marina Alves", "Educadora com experiência em oficinas práticas de tecnologia.", "Programação criativa", "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"))));
        testes.add(DynamicTest.dynamicTest("instrutores/contato: opcional", () -> assertDoesNotThrow(() -> new Instrutor(Controle.novo(Estado.ATIVO), "Marina Alves", "Educadora com experiência em oficinas práticas de tecnologia.", "Programação criativa", null))));
        testes.add(DynamicTest.dynamicTest("espacos: exemplo válido", () -> assertDoesNotThrow(() -> new Espaco(Controle.novo(Estado.ATIVO), "Laboratório Criativo", "Bloco A · sala 204", "Mesas modulares e pontos de energia.", 30))));
        testes.add(DynamicTest.dynamicTest("espacos/nome: obrigatório", () -> assertThrows(ErroDominio.class, () -> new Espaco(Controle.novo(Estado.ATIVO), null, "Bloco A · sala 204", "Mesas modulares e pontos de energia.", 30))));
        testes.add(DynamicTest.dynamicTest("espacos/nome: texto extenso", () -> assertThrows(ErroDominio.class, () -> new Espaco(Controle.novo(Estado.ATIVO), "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "Bloco A · sala 204", "Mesas modulares e pontos de energia.", 30))));
        testes.add(DynamicTest.dynamicTest("espacos/localizacao: obrigatório", () -> assertThrows(ErroDominio.class, () -> new Espaco(Controle.novo(Estado.ATIVO), "Laboratório Criativo", null, "Mesas modulares e pontos de energia.", 30))));
        testes.add(DynamicTest.dynamicTest("espacos/localizacao: texto extenso", () -> assertThrows(ErroDominio.class, () -> new Espaco(Controle.novo(Estado.ATIVO), "Laboratório Criativo", "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx", "Mesas modulares e pontos de energia.", 30))));
        testes.add(DynamicTest.dynamicTest("espacos/descricao: texto extenso", () -> assertThrows(ErroDominio.class, () -> new Espaco(Controle.novo(Estado.ATIVO), "Laboratório Criativo", "Bloco A · sala 204", "", 30))));
        testes.add(DynamicTest.dynamicTest("espacos/descricao: opcional", () -> assertDoesNotThrow(() -> new Espaco(Controle.novo(Estado.ATIVO), "Laboratório Criativo", "Bloco A · sala 204", null, 30))));
        testes.add(DynamicTest.dynamicTest("espacos/capacidade: abaixo do mínimo", () -> assertThrows(ErroDominio.class, () -> new Espaco(Controle.novo(Estado.ATIVO), "Laboratório Criativo", "Bloco A · sala 204", "Mesas modulares e pontos de energia.", 0))));
        testes.add(DynamicTest.dynamicTest("espacos/capacidade: acima do máximo", () -> assertThrows(ErroDominio.class, () -> new Espaco(Controle.novo(Estado.ATIVO), "Laboratório Criativo", "Bloco A · sala 204", "Mesas modulares e pontos de energia.", 1001))));
        testes.add(DynamicTest.dynamicTest("espacos/capacidade: opcional", () -> assertDoesNotThrow(() -> new Espaco(Controle.novo(Estado.ATIVO), "Laboratório Criativo", "Bloco A · sala 204", "Mesas modulares e pontos de energia.", null))));
        return testes.stream();
    }
}
